/*
 * LINDOWS kernel entry - phase 2 + runtime verification.
 * Freestanding C. Prints to the VGA text buffer AND to COM1 serial, so the
 * boot can be verified headlessly with `qemu -serial file:...`.
 * Compiled with i686-elf-gcc -ffreestanding -nostdlib.
 *
 * Profile policy: BUILD-TIME is the single source of truth. The profile name
 * comes from kernel/gen/profile_gen.h (generated by the build with
 * `PROFILE=...`). The old 3-second serial picker is gone from the boot path;
 * it lived only to prove serial input polling works, and it made every boot
 * pay a 3 s delay. (It can return later behind a debug flag once there is
 * profile *content* to choose between.)
 */
#include "gen/profile_gen.h"
#include "types.h"
#include "console.h"
#include "gdt.h"
#include "idt.h"
#include "panic.h"
#include "pmm.h"
#include "vmm.h"

/* Multiboot v1 handoff values, saved for later phases (paging needs the
 * memory map inside the info struct). */
u32 mb_magic;
u32 mb_info;

#define MB_BOOTLOADER_MAGIC 0x2BADB002u

/* Wait until pit_ticks reaches `target`, with a spin watchdog so a dead PIT
 * panics instead of hanging silently. */
static void wait_ticks(u32 target) {
    u32 spins = 0;
    while (pit_ticks < target) {
        __asm__ volatile("hlt");
        if (++spins > 100000000u)     /* ~ seconds of hlt without any tick */
            panic("PIT not ticking - timer IRQ dead", 0, 0);
    }
}

void kmain(u32 magic, u32 mbi) {
    mb_magic = magic;
    mb_info  = mbi;

    console_init();
    gdt_init();                       /* Phase 2: install protected-mode GDT */
    idt_init();                       /* Phase 2: IDT + PIC + 100 Hz timer   */

    console_puts("LINDOWS boot\r\n", CON_COLOR_CYAN);
    console_puts("profile: " PROFILE_NAME " (build-time)\r\n", CON_COLOR_CYAN);

    /* ---- earned verification, not narrative ---- */
    u32 t0 = pit_ticks;
    wait_ticks(t0 + 5);               /* ~50 ms of guaranteed IRQ0 ticks */
    console_puts("timer verified: ", CON_COLOR_GREEN);
    console_print_u32(pit_ticks - t0, CON_COLOR_WHITE);
    console_puts(" ticks in ~50ms (100 Hz PIT)\r\n", CON_COLOR_GREEN);

    console_puts("boot ok: COM1 serial up, VGA text up (scrolling)\r\n", CON_COLOR_GREEN);
    console_puts("phase 2: GDT installed (32-bit PM, flat memory, code+data)\r\n", CON_COLOR_YELLOW);
    console_puts("phase 2: IDT: 32 exceptions + 16 IRQs guarded, PIC-only, IRQ0 unmasked\r\n", CON_COLOR_YELLOW);

    /* ---- Phase 2: physical + virtual memory ---- */
    pmm_init(mb_info);
    console_puts("pmm: memory map ", CON_COLOR_YELLOW);
    console_puts(pmm_used_mmap() ? "multiboot mmap" : "mem_upper fallback", CON_COLOR_WHITE);
    console_puts(", ", CON_COLOR_YELLOW);
    console_print_u32(pmm_installed_frames(), CON_COLOR_WHITE);
    console_puts(" frames installed (", CON_COLOR_YELLOW);
    console_print_u32(pmm_free_frames(), CON_COLOR_WHITE);
    console_puts(" free)\r\n", CON_COLOR_YELLOW);

    vmm_init();
    vmm_verify();
    console_puts("vmm: paging ON (CR0.PG|WP): identity ", CON_COLOR_GREEN);
    console_print_u32(vmm_identity_frames() >> 8, CON_COLOR_WHITE);   /* MiB */
    console_puts(" MiB RAM, kernel alias @0xC0000000, recursive PD @0xFFFFF000\r\n", CON_COLOR_GREEN);

#ifdef LINDOWS_DEBUG
    console_puts("debug: multiboot magic ", CON_COLOR_RED);
    console_print_hex(magic, CON_COLOR_WHITE);
    console_puts(", mbi ", CON_COLOR_RED);
    console_print_hex(mbi, CON_COLOR_WHITE);
    console_puts(", t0=", CON_COLOR_RED);
    console_print_u32(t0, CON_COLOR_WHITE);
    console_puts("\r\n", CON_COLOR_WHITE);
#endif

    /* Phase 2 continues: heap, scheduler land here. Higher-half link
     * relocation next. */
#ifdef LINDOWS_FAULT_TEST
    /* Deliberate fault: ud2 -> #UD (invalid opcode). Exists to verify the
     * exception path + panic dump end-to-end (build with
     * -DLINDOWS_FAULT_TEST; never part of a normal kernel). A #UD is used
     * because it faults regardless of paging state. */
    __asm__ volatile("ud2");
#endif
#ifdef LINDOWS_PFAULT_TEST
    /* Deliberate page fault: address beyond every tracked frame and beyond
     * the identity map -> #PF, not-present (error code bit 0 = 0).
     * Build with -DLINDOWS_PFAULT_TEST; never part of a normal kernel. */
    volatile u32 pboom = *(volatile u32*)0x40000000u;   /* 1 GiB: unmapped */
    console_print_u32(pboom, CON_COLOR_RED);           /* never reached */
#endif
    for (;;) { __asm__ volatile("hlt"); }
}
